<?php
require '../config/db_conn.php';
$section=$_GET['section']??'all';$filterDate=$_GET['date']??'';$student=trim($_GET['student']??'');$where=[];
if($filterDate!==''){$where[]="DATE(a.TIME_IN)='".mysqli_real_escape_string($conn,$filterDate)."'";}
if($section!==''&&$section!=='all'){$where[]="s.SECTION='".mysqli_real_escape_string($conn,$section)."'";}
if($student!==''){$safe=mysqli_real_escape_string($conn,$student);$where[]="(a.STUDENT_ID='$safe' OR s.STUDENT_NAME LIKE '%$safe%')";}
$query="SELECT a.*,s.SECTION,s.STUDENT_NAME official_name FROM attendance a LEFT JOIN students s ON TRIM(a.STUDENT_ID)=TRIM(s.STUDENT_ID)";if($where)$query.=' WHERE '.implode(' AND ',$where);$query.=' ORDER BY a.TIME_IN DESC';$result=$conn->query($query);
if($result&&$result->num_rows):while($row=$result->fetch_assoc()):$time=new DateTime($row['TIME_IN']);$name=$row['official_name']?:$row['STUDENT_NAME'];?><tr class="transition hover:bg-slate-50"><td class="px-4 py-4 font-medium text-slate-700"><?= htmlspecialchars($row['STUDENT_ID']) ?></td><td class="px-4 py-4 font-bold text-slate-900"><?= htmlspecialchars($name) ?></td><td class="px-4 py-4"><span class="rounded-full bg-blue-50 px-3 py-1 text-xs font-bold text-blue-700"><?= htmlspecialchars($row['SECTION']??'N/A') ?></span></td><td class="px-4 py-4 text-slate-600"><?= $time->format('F j, Y') ?></td><td class="px-4 py-4 text-slate-600"><?= $time->format('g:i A') ?></td><td class="px-4 py-4"><span class="rounded-full bg-emerald-50 px-3 py-1 text-xs font-bold text-emerald-700">Present</span><a class="ml-3 text-xs font-bold text-blue-600" href="export-attendance.php?date=<?= urlencode($filterDate?:date('Y-m-d')) ?>&section=<?= urlencode($section) ?>&student_id=<?= urlencode($row['STUDENT_ID']) ?>">Export student</a></td></tr><?php endwhile;else:?><tr><td colspan="6" class="px-4 py-10 text-center text-slate-500">No matching attendance records.</td></tr><?php endif; ?>